20	    access::{GitCommitTrustEvidence, GitHeadDisposition},
21	    GitCommit, GitDataSource, VcsError,
22	};
23	
24	/// Record separator placed immediately before each commit's fields in
25	/// `git log --format=` output, so a commit message containing `\n` can
26	/// never be mistaken for a record boundary.
27	const RECORD_SEP: char = '\u{1e}';
28	
29	/// Unit separator between a commit's sha and its raw message body in
30	/// `git log --format=` output.
31	const FIELD_SEP: char = '\u{1f}';
32	
33	/// Closed release policy for ignored worktree artifacts. Repository ignore
34	/// rules are not authority to omit arbitrary release input from trust.
35	const RELEASE_IGNORED_ALLOWLIST: &[&str] = &[
36	    ".DS_Store",
37	    "target/",
38	    "bin/",
39	    ".moon/cache/",
40	    ".moon/docker/",
41	    ".claude/worktrees/",
42	    "mutants.out/",
43	    "lcov.info",
44	];
