195	/// One `git diff --raw -z` record, before Git's single-letter status is
196	/// mapped to a [`StagedChangeKindV1`] and file contents are read.
197	struct RawDiffEntry {
198	    path: String,
199	    /// The post-image Git file mode, or `None` for a pure deletion.
200	    new_mode: Option<u32>,
201	    status: char,
202	}
203	
204	/// Parses `git diff --raw -z --no-renames` output. Each record is two
205	/// `\0`-separated tokens: a `:<old-mode> <new-mode> <old-sha> <new-sha>
206	/// <status>` metadata line, then the path. `--no-renames` guarantees at
207	/// most one path per record (a rename or copy would otherwise emit two).
208	fn parse_raw_diff_z(raw: &str) -> Result<Vec<RawDiffEntry>, VcsError> {
209	    let mut entries = Vec::new();
210	    let mut tokens = raw.split('\0').filter(|token| !token.is_empty());
211	    while let Some(meta) = tokens.next() {
212	        let Some(meta) = meta.strip_prefix(':') else {
213	            return Err(VcsError::Git(format!(
214	                "unexpected token in `git diff --raw -z` output: {meta:?}"
215	            )));
216	        };
217	        let path = tokens.next().ok_or_else(|| {
218	            VcsError::Git("truncated `git diff --raw -z` output: missing a path after its metadata line".to_string())
219	        })?;
220	        let fields: Vec<&str> = meta.split(' ').collect();
221	        let [_old_mode, new_mode, _old_sha, _new_sha, status_field] = fields.as_slice() else {
222	            return Err(VcsError::Git(format!(
223	                "malformed `git diff --raw -z` metadata line: {meta:?}"
224	            )));
225	        };
226	        let status = status_field
227	            .chars()
228	            .next()
229	            .ok_or_else(|| VcsError::Git(format!("empty status in `git diff --raw -z` metadata line: {meta:?}")))?;
230	        let new_mode =
231	            if status == 'D' {
232	                None
233	            } else {
234	                Some(u32::from_str_radix(new_mode, 8).map_err(|error| {
235	                    VcsError::Git(format!("invalid Git mode `{new_mode}` in raw diff output: {error}"))
236	                })?)
237	            };
238	        entries.push(RawDiffEntry {
239	            path: path.to_string(),
240	            new_mode,
241	            status,
242	        });
243	    }
244	    Ok(entries)
245	}
