247	/// Maps a `git diff --raw` single-letter status to a [`StagedChangeKindV1`].
248	/// Any status this codebase does not have a named case for (Git's own docs
249	/// list `X` as "unknown") conservatively maps to `Unmerged`, which
250	/// [`callisto_model::ReleasePrCommitPlanV1::from_changes`] always rejects --
251	/// safe by construction rather than by an exhaustive status list here.
252	fn staged_change_kind(status: char) -> StagedChangeKindV1 {
253	    match status {
254	        'A' => StagedChangeKindV1::Added,
255	        'M' => StagedChangeKindV1::Modified,
256	        'D' => StagedChangeKindV1::Deleted,
257	        'R' => StagedChangeKindV1::Renamed,
258	        'C' => StagedChangeKindV1::Copied,
259	        'T' => StagedChangeKindV1::TypeChanged,
260	        _ => StagedChangeKindV1::Unmerged,
261	    }
262	}
