264	fn canonical_git_root(raw_root: &str) -> Result<PathBuf, VcsError> {
265	    if raw_root.is_empty() {
266	        return Err(VcsError::Git(
267	            "Git returned an empty repository root for release trust".to_string(),
268	        ));
269	    }
270	    dunce::canonicalize(raw_root).map_err(|error| {
271	        drop(error);
272	        VcsError::Git("could not canonicalize the Git repository root for release trust".to_string())
273	    })
274	}
