276	fn parse_release_worktree_status(status: &str) -> Result<Vec<PathBuf>, VcsError> {
277	    let mut allowed_ignored_paths = Vec::new();
278	    for record in status.split('\0').filter(|record| !record.is_empty()) {
279	        let Some(path) = record.strip_prefix("!! ") else {
280	            return Err(VcsError::Git(
281	                "release trust requires a worktree with no tracked or untracked files".to_string(),
282	            ));
283	        };
284	        let path = PathBuf::from(path);
285	        if !is_release_ignored_path_allowed(&path) {
286	            return Err(VcsError::Git(
287	                "release trust found an ignored path outside its fixed allowlist".to_string(),
288	            ));
289	        }
290	        allowed_ignored_paths.push(path);
291	    }
292	    allowed_ignored_paths.sort();
293	    allowed_ignored_paths.dedup();
294	    Ok(allowed_ignored_paths)
295	}
296	
297	fn is_release_ignored_path_allowed(path: &Path) -> bool {
298	    if path.is_absolute()
299	        || path
300	            .components()
301	            .any(|component| !matches!(component, std::path::Component::Normal(_)))
302	    {
303	        return false;
304	    }
305	    let rendered = path.to_string_lossy().replace('\\', "/");
306	    RELEASE_IGNORED_ALLOWLIST.iter().any(|allowed| {
307	        allowed.strip_suffix('/').map_or_else(
308	            || rendered == *allowed,
309	            |directory| rendered == directory || rendered.starts_with(&format!("{directory}/")),
310	        )
311	    })
312	}
