314	/// Compiles `glob` into a [`globset::GlobMatcher`], surfacing a malformed
315	/// pattern as [`VcsError::InvalidGlob`] rather than letting it silently
316	/// disable filtering (which would match every tag -- see
317	/// `GitRepository::list_tags`'s own doc comment for why that's a real
318	/// correctness risk for release tagging).
319	fn compile_glob(glob: &str) -> Result<globset::GlobMatcher, VcsError> {
320	    globset::Glob::new(glob)
321	        .map(|g| g.compile_matcher())
322	        .map_err(|e| VcsError::InvalidGlob {
323	            pattern: glob.to_string(),
324	            message: e.to_string(),
325	        })
326	}
