328	impl GitDataSource for ShellGit<'_> {
329	    fn head_sha(&self) -> Result<CommitSha, VcsError> {
330	        let output = self.runner.run("git", &["rev-parse", "HEAD"], &self.root)?;
331	        if !output.success() {
332	            return Err(VcsError::Git(format!(
333	                "`git rev-parse HEAD` failed in `{}`: {}",
334	                self.root.display(),
335	                redact_git_stderr(&output.stderr)
336	            )));
337	        }
338	        let sha_str = output.stdout_trimmed();
339	        CommitSha::parse(sha_str).map_err(|e| VcsError::Git(format!("could not parse HEAD SHA `{sha_str}`: {e}")))
340	    }
