342	    /// Always fetches the *full, unfiltered* tag list via `git tag --list`
343	    /// and applies `glob` (if any) locally with `globset` -- deliberately
344	    /// never delegates filtering to `git tag --list <pattern>`'s own
345	    /// (different) glob dialect. This is what guarantees byte-identical
346	    /// tag selection between this backend and the native `gix` path
347	    /// (`GitRepository::list_tags`, which also filters with `globset`)
348	    /// regardless of which one a caller ends up using.
349	    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
350	        let output = self.runner.run("git", &["tag", "--list"], &self.root)?;
351	        if !output.success() {
352	            // A directory with no `.git` anywhere in its ancestry is not a
353	            // hard failure -- it's the normal shape of a brand-new/pre-git
354	            // package, and callers (e.g. `status`) treat "no tags" as
355	            // "unreleased" rather than aborting. Any OTHER failure (a
356	            // corrupted or locked repository, a permissions error, ...)
357	            // must still surface as a real error rather than silently
358	            // becoming "zero tags".
359	            if !output.stderr.contains("not a git repository") {
360	                return Err(VcsError::Git(format!(
361	                    "`git tag --list` failed in `{}`: {}",
362	                    self.root.display(),
363	                    redact_git_stderr(&output.stderr)
364	                )));
365	            }
366	        }
367	        let all = output.stdout_lines().map(|s| s.to_string());
368	
369	        let matcher = glob.map(compile_glob).transpose()?;
370	
371	        Ok(all
372	            .filter(|t| matcher.as_ref().is_none_or(|m| m.is_match(t)))
373	            .map(TagName)
374	            .collect())
375	    }
