377	    fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
378	        let rev = format!("{refname}^{{commit}}");
379	        let output = self
380	            .runner
381	            .run("git", &["rev-parse", "--verify", "--quiet", &rev], &self.root)?;
382	
383	        if !output.success() {
384	            return Ok(None);
385	        }
386	        let sha_str = output.stdout_trimmed();
387	        if sha_str.is_empty() {
388	            return Ok(None);
389	        }
390	        Ok(CommitSha::parse(sha_str).ok())
391	    }
