393	    /// Shells `git log --no-merges --format=<RECORD_SEP>%H<FIELD_SEP>%B
394	    /// <range> [-- <pathspecs>]`, matching the native path field-for-field:
395	    /// `--no-merges` excludes merges like
396	    /// `GitRepository::commits_since_with_pathspec`'s parent-count skip;
397	    /// `<since>..HEAD` (or bare `HEAD`) gives the same
398	    /// exclusive-lower-bound range as the revwalk's stop-at-`since` logic;
399	    /// `-- <pathspecs>` reproduces `git log`'s own pathspec-prefix
400	    /// filtering.
401	    ///
402	    /// Deliberately doesn't pre-resolve `since_ref` via a separate
403	    /// `rev-parse`: an unresolvable ref already makes `git log
404	    /// <since_ref>..HEAD` fail (non-zero exit), surfaced below as `Err`
405	    /// like any other failure -- one shell call either way.
406	    fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError> {
407	        let mut args: Vec<String> = vec![
408	            "log".to_string(),
409	            "--no-merges".to_string(),
410	            format!("--format={RECORD_SEP}%H{FIELD_SEP}%B"),
411	        ];
412	
413	        match since_ref {
414	            Some(r) => args.push(format!("{r}..HEAD")),
415	            None => args.push("HEAD".to_string()),
416	        }
417	
418	        if !pathspecs.is_empty() {
419	            args.push("--".to_string());
420	            args.extend(pathspecs.iter().map(|p| p.display().to_string()));
421	        }
422	
423	        let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
424	        let output = self.runner.run("git", &arg_refs, &self.root)?;
425	
426	        if !output.success() {
427	            return Err(VcsError::Git(format!(
428	                "`git log` failed in `{}`: {}",
429	                self.root.display(),
430	                redact_git_stderr(&output.stderr)
431	            )));
432	        }
433	
434	        parse_git_log_output(&output.stdout, &self.root)
435	    }
