487	/// Parses the `<RECORD_SEP>%H<FIELD_SEP>%B`-formatted `git log` output
488	/// produced by [`ShellGit::commits_since`] into [`GitCommit`]s, splitting
489	/// each raw message on its first blank line into `summary`/`body` --
490	/// mirroring how `gix`'s own commit-message parsing (used by
491	/// `GitRepository::commits_since_with_pathspec`) splits title from body,
492	/// so both backends hand callers the same shape.
493	fn parse_git_log_output(stdout: &str, cwd: &Path) -> Result<Vec<GitCommit>, VcsError> {
494	    let mut commits = Vec::new();
495	
496	    for record in stdout.split(RECORD_SEP) {
497	        // `tformat:`-style `--format=` output (the default when the format
498	        // string doesn't start with `format:`/`tformat:`) appends a
499	        // trailing newline after every entry; strip it rather than the
500	        // message's own content.
501	        let record = record.trim_end_matches('\n');
502	        if record.is_empty() {
503	            continue;
504	        }
505	
506	        let Some((sha_str, message)) = record.split_once(FIELD_SEP) else {
507	            return Err(VcsError::Git(format!(
508	                "could not parse `git log` output in `{}` into commit records: expected a \
509	                 `<sha>{FIELD_SEP:?}<message>` record, got: {record:?}",
510	                cwd.display()
511	            )));
512	        };
513	
514	        let sha = CommitSha::parse(sha_str).map_err(|e| {
515	            VcsError::Git(format!(
516	                "could not parse `git log` output in `{}`: invalid commit SHA `{sha_str}`: {e}",
517	                cwd.display()
518	            ))
519	        })?;
520	
521	        let message = message.replace("\r\n", "\n");
522	        let (summary, body) = match message.split_once("\n\n") {
523	            Some((title, rest)) => (title.trim_end().to_string(), Some(rest.to_string())),
524	            None => (message.trim_end().to_string(), None),
525	        };
526	
527	        commits.push(GitCommit { sha, summary, body });
528	    }
529	
530	    Ok(commits)
531	}
