use std::io::Read;
use std::path::Path;
use std::process::Stdio;
use std::time::{Duration, Instant};

use callisto_model::{known_credential_env_values, redact_known_secrets, CommandError, CommandOutput, CommandRunner};

/// Caps how much of a subprocess's stdout/stderr this process will retain
/// in memory. The pipe is still drained in full past this point (bytes
/// beyond the cap are read and discarded, never accumulated) so a chatty
/// child can never deadlock waiting on a full OS pipe buffer -- this
/// bounds memory, not duration (`PUBLISH_TIMEOUT_SECS` bounds that
/// separately).
const MAX_CAPTURED_OUTPUT_BYTES: usize = 10 * 1024 * 1024;

pub struct CliCommandRunner;

impl CommandRunner for CliCommandRunner {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
        let output = std::process::Command::new(program)
            .args(args)
            .current_dir(cwd)
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .output();

        match output {
            Ok(o) => {
                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
                // Keep raw stderr available to callers for protocol/error
                // classification, but never leak credentials to the terminal.
                if !stderr.is_empty() {
                    let secrets = known_credential_env_values(std::env::vars());
                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
                }
                Ok(CommandOutput {
                    exit_code: o.status.code(),
                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
                    stderr,
                })
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(CommandError::NotFound {
                program: program.to_string(),
            }),
            Err(e) => Err(CommandError::Io {
                program: program.to_string(),
                message: e.to_string(),
            }),
        }
    }

    fn run_with_timeout(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        // `known_credential_env_values` is scanned here, at the trait-method
        // call site, rather than inside `run_with_timeout_impl` itself: this
        // keeps the impl fn pure and directly unit-testable with a synthetic
        // secrets list (no process-env mutation, which would race against
        // other tests running in parallel in this binary).
        run_with_timeout_impl(
            program,
            args,
            cwd,
            timeout,
            StderrMode::Live,
            known_credential_env_values(std::env::vars()),
        )
    }

    fn run_quiet(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        // Quiet mode never echoes stderr live (see `StderrMode::Quiet`
        // below), so there's nothing to redact -- pass an empty secrets
        // list rather than paying for an env scan that can only go unused.
        run_with_timeout_impl(program, args, cwd, timeout, StderrMode::Quiet, Vec::new())
    }
}

/// Controls whether [`run_with_timeout_impl`]'s stderr reader thread prints
/// each line live as it arrives. Captured `CommandOutput.stderr` is
/// identical either way -- this only affects what's echoed to the
/// terminal while the subprocess runs.
#[derive(Clone, Copy, PartialEq, Eq)]
enum StderrMode {
    Live,
    Quiet,
}

/// `live_secrets`: known-credential values (see
/// [`callisto_model::known_credential_env_values`]) to redact from each
/// line *before* it's echoed live to the terminal via `eprintln!`. This is
/// deliberately separate from -- and does not affect -- the `captured`
/// buffer that becomes the returned `CommandOutput.stderr`: that copy must
/// stay byte-for-byte raw so downstream classifiers (e.g.
/// `extract_retry_after_duration`, `detect_auth_failure`) can still match
/// exact upstream text. Callers pass the secrets list in rather than this
/// function reading the environment itself, keeping it pure and testable
/// with a synthetic list.
fn run_with_timeout_impl(
    program: &str,
    args: &[&str],
    cwd: &Path,
    timeout: Duration,
    stderr_mode: StderrMode,
    live_secrets: Vec<String>,
) -> Result<CommandOutput, CommandError> {
    let mut child = std::process::Command::new(program)
        .args(args)
        .current_dir(cwd)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| {
            if e.kind() == std::io::ErrorKind::NotFound {
                CommandError::NotFound {
                    program: program.to_string(),
                }
            } else {
                CommandError::Io {
                    program: program.to_string(),
                    message: e.to_string(),
                }
            }
        })?;

    // Read stdout/stderr in separate threads to prevent pipe-buffer deadlock
    // when the child produces output while we wait for it to exit.
    let stdout_handle = child.stdout.take().unwrap();
    let stderr_handle = child.stderr.take().unwrap();

    // The reader threads signal completion over a channel rather than
    // being joined directly. Killing (or the natural exit of) the
    // direct child does NOT close pipe fds held open by a descendant
    // process that inherited them (common for npm/cargo/python publish
    // lifecycle scripts spawning subprocesses). If that happens, the
    // blocking `read()` inside these threads never returns. Using
    // `recv_timeout` below lets us bound how long we wait for them
    // without ever blocking the caller indefinitely.
    let (stdout_tx, stdout_rx) = std::sync::mpsc::channel::<String>();
    let (stderr_tx, stderr_rx) = std::sync::mpsc::channel::<String>();

    std::thread::spawn(move || {
        let mut reader = stdout_handle;
        let mut captured: Vec<u8> = Vec::new();
        let mut truncated = false;
        let mut chunk = [0u8; 65536];
        loop {
            match reader.read(&mut chunk) {
                Ok(0) => break,
                Ok(n) => {
                    // Bytes past the cap are still read (draining the
                    // pipe so the child never blocks on a full buffer)
                    // but not retained.
                    if !truncated {
                        let remaining = MAX_CAPTURED_OUTPUT_BYTES - captured.len();
                        let take = n.min(remaining);
                        captured.extend_from_slice(&chunk[..take]);
                        if take < n {
                            truncated = true;
                        }
                    }
                }
                Err(_) => break,
            }
        }
        let mut text = String::from_utf8_lossy(&captured).into_owned();
        if truncated {
            text.push_str("\n...[output truncated]\n");
        }
        drop(stdout_tx.send(text));
    });
    // Stream stderr line-by-line so publish progress (cargo/npm/twine
    // write to stderr) appears in real time rather than after the
    // process exits, while capping the accumulated text returned to
    // the caller. Deliberately reads raw bytes rather than using
    // `BufReader::lines()`: that iterator has no size bound on a
    // single line, so a flood with no newlines at all would still
    // buffer unboundedly inside it before ever yielding a line to cap.
    // `stderr_mode` gates only the live eprintln -- captured output is
    // identical either way (Live vs. Quiet).
    //
    // NOTE: captured output is no longer necessarily byte-identical to
    // what was printed live. Each line handed to `eprintln!` is redacted
    // via `live_secrets` first (registry CLIs can echo a credential
    // verbatim in their own stderr diagnostics), while `captured` -- and
    // therefore the returned `CommandOutput.stderr` -- deliberately stays
    // raw so error classifiers keep matching exact upstream text. For a
    // credential-bearing line, the terminal sees `[REDACTED]`; the
    // returned `CommandOutput.stderr` still has the real value.
    std::thread::spawn(move || {
        let mut reader = stderr_handle;
        let mut captured: Vec<u8> = Vec::new();
        let mut truncated = false;
        let mut pending_line: Vec<u8> = Vec::new();
        let mut chunk = [0u8; 65536];
        loop {
            match reader.read(&mut chunk) {
                Ok(0) => break,
                Ok(n) => {
                    let data = &chunk[..n];
                    for &b in data {
                        if b == b'\n' {
                            if pending_line.last() == Some(&b'\r') {
                                pending_line.pop();
                            }
                            if stderr_mode == StderrMode::Live {
                                let line = redact_known_secrets(&String::from_utf8_lossy(&pending_line), &live_secrets);
                                eprintln!("{line}");
                            }
                            pending_line.clear();
                        } else if pending_line.len() < MAX_CAPTURED_OUTPUT_BYTES {
                            pending_line.push(b);
                        }
                    }
                    if !truncated {
                        let remaining = MAX_CAPTURED_OUTPUT_BYTES - captured.len();
                        let take = data.len().min(remaining);
                        captured.extend_from_slice(&data[..take]);
                        if take < data.len() {
                            truncated = true;
                        }
                    }
                }
                Err(_) => break,
            }
        }
        if !pending_line.is_empty() {
            if pending_line.last() == Some(&b'\r') {
                pending_line.pop();
            }
            if stderr_mode == StderrMode::Live {
                let line = redact_known_secrets(&String::from_utf8_lossy(&pending_line), &live_secrets);
                eprintln!("{line}");
            }
        }
        let mut text = String::from_utf8_lossy(&captured).into_owned();
        if truncated {
            text.push_str("\n...[output truncated]\n");
        }
        drop(stderr_tx.send(text));
    });

    // Grace period to wait for the reader threads after the direct
    // child has exited (or been killed). Bounded so a lingering
    // descendant holding the pipe open can never hang the caller.
    const READER_GRACE: Duration = Duration::from_secs(3);

    let deadline = Instant::now() + timeout;
    let status = loop {
        match child.try_wait().map_err(|e| CommandError::Io {
            program: program.to_string(),
            message: e.to_string(),
        })? {
            Some(s) => break s,
            None => {
                if Instant::now() >= deadline {
                    drop(child.kill());
                    drop(child.wait());
                    // Reader threads are intentionally not joined here:
                    // if a descendant process is still holding a pipe
                    // fd open, join() could block forever. We wait a
                    // bounded grace period for output, then abandon the
                    // threads (they leak until the descendant
                    // eventually exits and closes the fd -- a thread
                    // leak, not a memory-safety issue).
                    let stdout = stdout_rx.recv_timeout(READER_GRACE).ok();
                    let stderr = stderr_rx.recv_timeout(READER_GRACE).ok();
                    if stdout.is_none() || stderr.is_none() {
                        eprintln!(
                            "warning: `{program}` timed out and a descendant process \
                                 appears to still hold its output pipes open; captured \
                                 output may be incomplete"
                        );
                    }
                    return Err(CommandError::TimedOut {
                        program: program.to_string(),
                        seconds: timeout.as_secs(),
                    });
                }
                std::thread::sleep(Duration::from_millis(50));
            }
        }
    };

    // The direct child has exited on its own. Even so, a descendant
    // process can still hold the pipe fds open (e.g. a backgrounded
    // job spawned by a shell script), so bound the wait here too.
    let stdout_result = stdout_rx.recv_timeout(READER_GRACE);
    let stderr_result = stderr_rx.recv_timeout(READER_GRACE);
    if stdout_result.is_err() || stderr_result.is_err() {
        eprintln!(
            "warning: `{program}` exited but a descendant process appears to still \
                 hold its output pipes open; captured output may be incomplete"
        );
    }

    Ok(CommandOutput {
        exit_code: status.code(),
        stdout: stdout_result.unwrap_or_default(),
        stderr: stderr_result.unwrap_or_default(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn run_with_timeout_kills_slow_process_and_returns_timed_out() {
        let runner = CliCommandRunner;
        // sleep for 1 second with a 100ms timeout — process must be killed.
        let err = runner
            .run_with_timeout("sleep", &["1"], std::path::Path::new("."), Duration::from_millis(100))
            .unwrap_err();
        assert!(
            matches!(err, CommandError::TimedOut { .. }),
            "expected TimedOut, got: {err:?}"
        );
    }

    #[test]
    fn run_with_timeout_returns_output_for_fast_process() {
        let runner = CliCommandRunner;
        let out = runner
            .run_with_timeout("true", &[], std::path::Path::new("."), Duration::from_secs(5))
            .unwrap();
        assert!(out.success());
    }

    /// Regression test for a hung-descendant deadlock: killing the direct
    /// child does not close pipe fds inherited by a grandchild process that
    /// outlives it. The direct child (`sh`) exits almost immediately, but a
    /// backgrounded grandchild (`sleep 30`) keeps stderr open well past
    /// that. If the reader threads are joined unconditionally, this call
    /// hangs for ~30s regardless of the requested timeout. The fix bounds
    /// how long we wait on the reader threads so the call always returns
    /// promptly.
    #[test]
    fn run_with_timeout_bounds_reader_join_when_descendant_holds_pipe_open() {
        let runner = CliCommandRunner;
        let start = Instant::now();
        let result = runner.run_with_timeout(
            "sh",
            &["-c", "sleep 30 >&2 & exit 0"],
            std::path::Path::new("."),
            Duration::from_secs(2),
        );
        let elapsed = start.elapsed();
        assert!(
            elapsed < Duration::from_secs(6),
            "run_with_timeout must not block on a descendant process holding \
             stdio pipes open; took {elapsed:?}, result: {result:?}"
        );
        assert!(
            result.is_ok(),
            "expected Ok despite a lingering descendant holding the pipe open, got: {result:?}"
        );
    }

    /// F-007: subprocess stderr must be streamed line-by-line rather than
    /// buffered until process exit. The fix: switch from `read_to_string`
    /// (accumulates everything) to a `BufReader::lines` loop that emits each
    /// line to the terminal immediately while still accumulating the full
    /// text for caller analysis.
    ///
    /// We verify that `CommandOutput::stderr` still contains the full stderr
    /// text after streaming (so callers can still classify errors from it).
    #[test]
    fn run_with_timeout_stderr_is_fully_captured_after_streaming() {
        let runner = CliCommandRunner;
        // A process that prints multiple lines to stderr, one at a time.
        // Using sh -c with printf to emit to stderr.
        let out = runner
            .run_with_timeout(
                "sh",
                &["-c", "echo line1 >&2; echo line2 >&2"],
                std::path::Path::new("."),
                Duration::from_secs(5),
            )
            .unwrap();

        assert!(out.success());
        assert!(
            out.stderr.contains("line1") && out.stderr.contains("line2"),
            "stderr must contain all emitted lines even when streamed; got: {:?}",
            out.stderr
        );
    }

    /// Regression test for the timeout-KILL branch's grace-period logic
    /// (runner.rs:124-146), structurally similar to but independently
    /// written from the normal-exit branch's (runner.rs:153-163, covered
    /// by `run_with_timeout_bounds_reader_join_when_descendant_holds_pipe_open`).
    /// That test's child (`sh`) exits almost immediately, only exercising
    /// the exit branch. Here the child (`sh -c "sleep 30 >&2 & sleep 10"`)
    /// outlives the timeout, so `run_with_timeout` must actually kill it,
    /// while a backgrounded grandchild (`sleep 30 >&2`) keeps stderr open
    /// independently of the kill.
    ///
    /// The warning is emitted via `eprintln!` inside `run_with_timeout`
    /// (not captured in `CommandOutput`), so this test re-execs the binary
    /// as a child with `--nocapture` to capture real OS-level stderr
    /// instead of having it swallowed by the outer harness.
    #[test]
    fn run_with_timeout_warns_on_timeout_branch_when_descendant_holds_pipe_open() {
        const CHILD_ENV: &str = "CALLISTO_RUN_TIMEOUT_KILL_CHILD";

        if std::env::var(CHILD_ENV).is_ok() {
            let runner = CliCommandRunner;
            // `sh` on this platform forks a separate process for the
            // foreground `sleep 10` rather than exec-replacing itself (it
            // must remain able to reap the backgrounded job), so killing
            // the direct child does not kill either descendant. Both the
            // backgrounded `sleep 30` and the foreground `sleep 10` inherit
            // the piped stdout/stderr fds unless redirected away, so each
            // is redirected explicitly: `sleep 30`'s stdout goes to
            // /dev/null so only its stderr lingers (the condition under
            // test), and `sleep 10`'s stdout/stderr both go to /dev/null so
            // it doesn't *also* hold either pipe open, which would stack a
            // second sequential 3s grace wait on top of the first.
            drop(runner.run_with_timeout(
                "sh",
                &["-c", "sleep 30 >&2 1>/dev/null & sleep 10 >/dev/null 2>&1"],
                std::path::Path::new("."),
                Duration::from_millis(800),
            ));
            return;
        }

        let exe = std::env::current_exe().expect("current_exe should be available in tests");
        let start = Instant::now();
        let output = std::process::Command::new(exe)
            .arg("--exact")
            .arg("runner::tests::run_with_timeout_warns_on_timeout_branch_when_descendant_holds_pipe_open")
            .arg("--nocapture")
            .env(CHILD_ENV, "1")
            .output()
            .expect("failed to re-exec test binary");
        let elapsed = start.elapsed();

        assert!(
            elapsed < Duration::from_secs(6),
            "run_with_timeout's timeout-kill branch must not block past its \
             bounded grace period even when a descendant holds stdio pipes \
             open; took {elapsed:?}"
        );

        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            stderr.contains("timed out and a descendant process appears to still hold its output pipes open"),
            "expected the timeout branch's specific warning text in child stderr, got: {stderr}"
        );
    }

    /// A subprocess that writes far more than `MAX_CAPTURED_OUTPUT_BYTES`
    /// to stdout must not have all of it retained in `CommandOutput` (an
    /// unbounded accumulation is a memory-exhaustion DoS before the
    /// wall-clock publish timeout ever fires), but the pipe must still be
    /// drained in full -- proven here by the call completing well within
    /// its timeout instead of hanging (a reader that stops calling
    /// `read()` after the cap would leave the child blocked writing to a
    /// full OS pipe buffer).
    #[test]
    fn run_with_timeout_caps_accumulated_stdout_and_still_drains_the_pipe() {
        let runner = CliCommandRunner;
        let over_cap = MAX_CAPTURED_OUTPUT_BYTES + 1_000_000;
        let start = Instant::now();
        let out = runner
            .run_with_timeout(
                "sh",
                &["-c", &format!("head -c {over_cap} /dev/zero")],
                std::path::Path::new("."),
                Duration::from_secs(30),
            )
            .unwrap();
        let elapsed = start.elapsed();

        assert!(out.success());
        assert!(
            elapsed < Duration::from_secs(15),
            "must not hang waiting for the child to finish writing past the cap; took {elapsed:?}"
        );
        assert!(
            out.stdout.len() < over_cap,
            "captured stdout must be bounded, not the full {over_cap} bytes written; got {} bytes",
            out.stdout.len()
        );
        assert!(
            out.stdout.contains("[output truncated]"),
            "truncated output must say so"
        );
    }

    /// Same as the stdout case, but for stderr -- and deliberately with NO
    /// newlines at all, so the flood can't be capped by a per-line
    /// mechanism (a `BufReader::lines()`-based reader has no size bound on
    /// a single line and would buffer the entire flood internally before
    /// ever handing a line back, defeating any cap applied only after a
    /// line is yielded).
    #[test]
    fn run_with_timeout_caps_accumulated_stderr_with_no_newlines_and_still_drains_the_pipe() {
        let runner = CliCommandRunner;
        let over_cap = MAX_CAPTURED_OUTPUT_BYTES + 1_000_000;
        let start = Instant::now();
        let out = runner
            .run_with_timeout(
                "sh",
                &["-c", &format!("head -c {over_cap} /dev/zero >&2")],
                std::path::Path::new("."),
                Duration::from_secs(30),
            )
            .unwrap();
        let elapsed = start.elapsed();

        assert!(out.success());
        assert!(
            elapsed < Duration::from_secs(15),
            "must not hang waiting for the child to finish writing past the cap; took {elapsed:?}"
        );
        assert!(
            out.stderr.len() < over_cap,
            "captured stderr must be bounded, not the full {over_cap} bytes written; got {} bytes",
            out.stderr.len()
        );
        assert!(
            out.stderr.contains("[output truncated]"),
            "truncated output must say so"
        );
    }

    /// Output comfortably under the cap must be completely unaffected --
    /// no truncation marker, byte-for-byte length preserved.
    #[test]
    fn run_with_timeout_does_not_truncate_output_under_the_cap() {
        let runner = CliCommandRunner;
        let out = runner
            .run_with_timeout(
                "sh",
                &["-c", "printf 'hello stdout'; printf 'hello stderr' >&2"],
                std::path::Path::new("."),
                Duration::from_secs(5),
            )
            .unwrap();

        assert_eq!(out.stdout, "hello stdout");
        assert!(!out.stdout.contains("[output truncated]"));
        assert!(out.stderr.contains("hello stderr"));
        assert!(!out.stderr.contains("[output truncated]"));
    }

    /// `run_quiet` must still fully capture stderr into the returned
    /// `CommandOutput` -- only the live terminal echo is suppressed, not
    /// the capture callers rely on to classify probe results (e.g.
    /// `npm view`'s 404-shaped "not published yet" text).
    #[test]
    fn run_quiet_still_captures_stderr_in_output() {
        let runner = CliCommandRunner;
        let out = runner
            .run_quiet(
                "sh",
                &["-c", "echo captured-probe-text >&2"],
                std::path::Path::new("."),
                Duration::from_secs(5),
            )
            .unwrap();
        assert!(
            out.stderr.contains("captured-probe-text"),
            "run_quiet must still capture stderr, got: {:?}",
            out.stderr
        );
    }

    /// The actual point of `run_quiet`: it must not echo stderr live to the
    /// terminal the way `run_with_timeout` does. Because the live echo goes
    /// via `eprintln!` from inside `run_quiet` itself (not captured in
    /// `CommandOutput`), this re-execs the current test binary as a child
    /// process with `--nocapture` so the real OS-level stderr can be
    /// observed and asserted on -- same pattern as
    /// `run_with_timeout_warns_on_timeout_branch_when_descendant_holds_pipe_open`.
    #[test]
    fn run_quiet_does_not_stream_stderr_live() {
        const CHILD_ENV: &str = "CALLISTO_RUN_QUIET_CHILD";

        if std::env::var(CHILD_ENV).is_ok() {
            let runner = CliCommandRunner;
            let out = runner
                .run_quiet(
                    "sh",
                    &["-c", "echo should-not-appear-live >&2"],
                    std::path::Path::new("."),
                    Duration::from_secs(5),
                )
                .expect("run_quiet must succeed");
            // Positive proof the call actually ran and captured correctly,
            // not just "produced no live output" -- a crashed or no-op
            // child would leave the negative assertion below vacuously
            // true. Printed to the child's own real stdout, entirely
            // separate from anything `run_quiet` itself captures or emits.
            assert!(
                out.stderr.contains("should-not-appear-live"),
                "run_quiet must still capture the text it doesn't stream live"
            );
            println!("CHILD_REACHED_AND_VERIFIED_CAPTURE");
            return;
        }

        let exe = std::env::current_exe().expect("current_exe should be available in tests");
        let output = std::process::Command::new(exe)
            .arg("--exact")
            .arg("runner::tests::run_quiet_does_not_stream_stderr_live")
            .arg("--nocapture")
            .env(CHILD_ENV, "1")
            .output()
            .expect("failed to re-exec test binary");

        assert!(
            output.status.success(),
            "child process must exit successfully, got: {:?}, stderr: {}",
            output.status,
            String::from_utf8_lossy(&output.stderr)
        );
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert!(
            stdout.contains("CHILD_REACHED_AND_VERIFIED_CAPTURE"),
            "child must have actually reached and verified the run_quiet call, not crashed \
             or no-op'd before it; got stdout: {stdout}"
        );

        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            !stderr.contains("should-not-appear-live"),
            "run_quiet must not stream stderr live to the terminal, got: {stderr}"
        );
    }

    /// Sibling regression guard: `run_with_timeout` (the live-streaming
    /// path `run_quiet` is deliberately different from) must still echo
    /// live -- otherwise this pair of tests could both pass by accident if
    /// `stderr_mode` were wired backwards.
    #[test]
    fn run_with_timeout_still_streams_stderr_live() {
        const CHILD_ENV: &str = "CALLISTO_RUN_TIMEOUT_LIVE_CHILD";

        if std::env::var(CHILD_ENV).is_ok() {
            let runner = CliCommandRunner;
            drop(runner.run_with_timeout(
                "sh",
                &["-c", "echo should-appear-live >&2"],
                std::path::Path::new("."),
                Duration::from_secs(5),
            ));
            return;
        }

        let exe = std::env::current_exe().expect("current_exe should be available in tests");
        let output = std::process::Command::new(exe)
            .arg("--exact")
            .arg("runner::tests::run_with_timeout_still_streams_stderr_live")
            .arg("--nocapture")
            .env(CHILD_ENV, "1")
            .output()
            .expect("failed to re-exec test binary");

        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            stderr.contains("should-appear-live"),
            "run_with_timeout must still stream stderr live, got: {stderr}"
        );
    }

    /// Security regression: the live-streamed stderr copy must be redacted
    /// the same way the captured/returned copy already is (see
    /// `publish_client::redact_stderr`), but the *captured* copy handed
    /// back in `CommandOutput` must remain completely raw -- classifiers
    /// like `extract_retry_after_duration`/`detect_auth_failure` need to
    /// match exact upstream text. Calls the private `run_with_timeout_impl`
    /// directly with a synthetic `live_secrets` list (no re-exec needed:
    /// this only inspects the returned value, not real OS-level stderr).
    #[test]
    fn run_with_timeout_impl_redacts_known_secret_from_live_echo_but_not_captured_output() {
        let secret = "sekrit-token-value";
        let out = run_with_timeout_impl(
            "sh",
            &["-c", &format!("echo {secret} >&2")],
            std::path::Path::new("."),
            Duration::from_secs(5),
            StderrMode::Live,
            vec![secret.to_string()],
        )
        .unwrap();
        assert!(
            out.stderr.contains(secret),
            "captured CommandOutput.stderr must stay raw/unredacted even when the live \
             echo is redacted, got: {:?}",
            out.stderr
        );
    }

    /// Same regression, exercised through the real public `run_with_timeout`
    /// entry point: a known-credential env var (`NPM_TOKEN`) present in the
    /// process environment must be scrubbed from the *live* terminal echo.
    /// Uses the re-exec pattern (see `run_with_timeout_still_streams_stderr_live`)
    /// because the live echo goes via `eprintln!`, not `CommandOutput`.
    #[test]
    fn run_with_timeout_redacts_known_credential_env_value_from_live_stderr_echo() {
        const CHILD_ENV: &str = "CALLISTO_RUN_TIMEOUT_REDACT_CHILD";
        const TOKEN: &str = "leak-me-1234";

        if std::env::var(CHILD_ENV).is_ok() {
            let runner = CliCommandRunner;
            drop(runner.run_with_timeout(
                "sh",
                &["-c", "echo leak-me-1234 >&2"],
                std::path::Path::new("."),
                Duration::from_secs(5),
            ));
            return;
        }

        let exe = std::env::current_exe().expect("current_exe should be available in tests");
        let output = std::process::Command::new(exe)
            .arg("--exact")
            .arg("runner::tests::run_with_timeout_redacts_known_credential_env_value_from_live_stderr_echo")
            .arg("--nocapture")
            .env(CHILD_ENV, "1")
            .env("NPM_TOKEN", TOKEN)
            .output()
            .expect("failed to re-exec test binary");

        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            !stderr.contains(TOKEN),
            "live-streamed stderr must not contain the raw known-credential value, got: {stderr}"
        );
        assert!(
            stderr.contains("[REDACTED]"),
            "live-streamed stderr must contain the redaction marker in place of the \
             credential, got: {stderr}"
        );
    }

    #[test]
    fn run_redacts_known_credential_env_value_from_live_stderr_echo() {
        const CHILD_ENV: &str = "CALLISTO_RUN_REDACT_CHILD";
        const TOKEN: &str = "run-leak-1234";

        if std::env::var(CHILD_ENV).is_ok() {
            let runner = CliCommandRunner;
            let output = runner
                .run("sh", &["-c", "echo run-leak-1234 >&2"], std::path::Path::new("."))
                .expect("run must capture child output");
            assert!(output.stderr.contains(TOKEN), "captured stderr must remain raw");
            return;
        }

        let exe = std::env::current_exe().expect("current_exe should be available in tests");
        let output = std::process::Command::new(exe)
            .arg("--exact")
            .arg("runner::tests::run_redacts_known_credential_env_value_from_live_stderr_echo")
            .arg("--nocapture")
            .env(CHILD_ENV, "1")
            .env("NPM_TOKEN", TOKEN)
            .output()
            .expect("failed to re-exec test binary");

        assert!(output.status.success(), "child test must succeed");
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            !stderr.contains(TOKEN),
            "raw credential leaked to live stderr: {stderr}"
        );
        assert!(stderr.contains("[REDACTED]"), "redaction marker missing: {stderr}");
    }

    /// Guards against over-redaction breaking downstream error classification:
    /// even when a known-credential env var is present and appears in the
    /// child's stderr alongside a rate-limit/auth marker, the *captured*
    /// `CommandOutput.stderr` returned to the caller must remain raw so
    /// `extract_retry_after_duration`/`detect_auth_failure`-style matching
    /// against exact upstream text keeps working. Re-execs so the child
    /// actually has `NPM_TOKEN` set when it calls `run_with_timeout`.
    #[test]
    fn run_with_timeout_still_captures_unredacted_stderr_for_classification_even_with_known_secret_present() {
        const CHILD_ENV: &str = "CALLISTO_RUN_TIMEOUT_CAPTURE_CHILD";
        const TOKEN: &str = "tok-abcd-9999";

        if std::env::var(CHILD_ENV).is_ok() {
            let runner = CliCommandRunner;
            let out = runner
                .run_with_timeout(
                    "sh",
                    &["-c", &format!("echo '429 too many requests, token={TOKEN}' >&2")],
                    std::path::Path::new("."),
                    Duration::from_secs(5),
                )
                .expect("run_with_timeout must succeed");
            assert!(
                out.stderr.contains(TOKEN),
                "captured CommandOutput.stderr must retain the raw token for classifiers \
                 like extract_retry_after_duration/detect_auth_failure, got: {:?}",
                out.stderr
            );
            assert!(
                out.stderr.contains("429"),
                "captured stderr must retain the rate-limit marker text, got: {:?}",
                out.stderr
            );
            println!("CHILD_REACHED_AND_VERIFIED_CAPTURE");
            return;
        }

        let exe = std::env::current_exe().expect("current_exe should be available in tests");
        let output = std::process::Command::new(exe)
            .arg("--exact")
            .arg(
                "runner::tests::run_with_timeout_still_captures_unredacted_stderr_for_classification_even_with_known_secret_present",
            )
            .arg("--nocapture")
            .env(CHILD_ENV, "1")
            .env("NPM_TOKEN", TOKEN)
            .output()
            .expect("failed to re-exec test binary");

        assert!(
            output.status.success(),
            "child process must exit successfully, got: {:?}, stderr: {}",
            output.status,
            String::from_utf8_lossy(&output.stderr)
        );
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert!(
            stdout.contains("CHILD_REACHED_AND_VERIFIED_CAPTURE"),
            "child must have actually reached and verified capture, not crashed or no-op'd \
             before it; got stdout: {stdout}"
        );
    }

    /// `run_quiet` never streams live at all (see `run_quiet_does_not_stream_stderr_live`),
    /// which means its call site should be able to skip scanning the
    /// environment for credentials entirely (`Vec::new()` short-circuit,
    /// rather than `known_credential_env_values(std::env::vars())`). This
    /// proves the externally-observable half of that: even with a known
    /// credential env var set, the live echo stays completely absent --
    /// neither the raw value nor a `[REDACTED]` marker appears -- which is
    /// what "simply absent" rather than "present-then-redacted" looks like
    /// from outside the process.
    #[test]
    fn run_quiet_does_not_stream_stderr_live_even_with_known_credential_env_value_present() {
        const CHILD_ENV: &str = "CALLISTO_RUN_QUIET_SECRET_CHILD";
        const TOKEN: &str = "quiet-leak-5678";

        if std::env::var(CHILD_ENV).is_ok() {
            let runner = CliCommandRunner;
            let out = runner
                .run_quiet(
                    "sh",
                    &["-c", &format!("echo {TOKEN} >&2")],
                    std::path::Path::new("."),
                    Duration::from_secs(5),
                )
                .expect("run_quiet must succeed");
            assert!(
                out.stderr.contains(TOKEN),
                "run_quiet must still capture the raw text it doesn't stream live"
            );
            println!("CHILD_REACHED_AND_VERIFIED_CAPTURE");
            return;
        }

        let exe = std::env::current_exe().expect("current_exe should be available in tests");
        let output = std::process::Command::new(exe)
            .arg("--exact")
            .arg("runner::tests::run_quiet_does_not_stream_stderr_live_even_with_known_credential_env_value_present")
            .arg("--nocapture")
            .env(CHILD_ENV, "1")
            .env("NPM_TOKEN", TOKEN)
            .output()
            .expect("failed to re-exec test binary");

        assert!(
            output.status.success(),
            "child process must exit successfully, got: {:?}, stderr: {}",
            output.status,
            String::from_utf8_lossy(&output.stderr)
        );
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert!(
            stdout.contains("CHILD_REACHED_AND_VERIFIED_CAPTURE"),
            "child must have actually reached and verified capture; got stdout: {stdout}"
        );

        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            !stderr.contains(TOKEN),
            "run_quiet must not stream the credential live, redacted or not, got: {stderr}"
        );
        assert!(
            !stderr.contains("[REDACTED]"),
            "run_quiet's zero-cost path passes Vec::new() and performs no live echo at all, \
             so no redaction marker should appear either -- proves the short-circuit is \
             actually taken rather than redacting-then-suppressing, got: {stderr}"
        );
    }
}

//! The `pdk`-feature `CommandRunner` impl for [`crate::runner::MoonCommandRunner`].
//! Split into its own file so `--ignore-filename-regex` can exclude it from
//! `cargo llvm-cov` reports: this code calls Extism-host-only `extern "C"`
//! imports (via `warpgate_pdk::exec`) that only resolve when linked against
//! a real wasm32-wasip1 Extism host, so `cargo-llvm-cov` (which instruments
//! a native build) can never observe it executing. It IS black-box tested --
//! via `tests/moon_wasm_sandbox.rs`, which drives the real compiled
//! `callisto-moon.wasm` artifact through an actual wasmtime-backed Extism
//! host -- just not by anything `cargo-llvm-cov`'s native instrumentation
//! can see.

use std::path::Path;

use callisto_model::{CommandError, CommandOutput, CommandRunner};

use crate::runner::{classify_host_failure, MoonCommandRunner};

// Under wasm32-wasip1 (the `pdk` build target), the WASI guest cannot spawn
// child processes at all — `std::process::Command` fails unconditionally.
// moon's PDK bridges process execution back to the host via the
// `exec_command` Extism host function; `warpgate_pdk::exec` is the typed
// wrapper around that host-fn call. A dedicated R&D spike confirmed
// gitoxide's low-level crates cannot read object content under
// wasm32-wasip1 either (memmap2 has no WASI backend), ruling out
// native in-guest git access as an alternative to this host-exec seam;
// see the "gix-in-WASM spike ruled out" finding in the external
// callisto-findings ledger (sibling repo: callisto-findings/FINDINGS.md)
// for the full writeup.
//
// IMPORTANT (bug found and fixed via black-box testing against the real
// wasm sandbox, see `tests/moon_wasm_sandbox.rs`): `warpgate`'s host-side
// `exec_command` implementation (`warpgate::host::exec_command`, in the
// pinned `warpgate` 0.30.5 this crate resolves to transitively) does NOT
// report "command not found" as a normal `ExecCommandOutput`/error value the
// guest's `warpgate_pdk::exec` can catch. Instead, when the requested
// program can't be resolved on `PATH`
// (`system_env::find_command_on_path` returns `None`), the host function's
// own Rust closure returns `Err(WarpgatePluginError::MissingCommand)`
// directly. Extism host functions that return `Err` from their native
// closure abort the *entire* plugin call as a host-function failure — this
// is NOT routed back into the guest as a value `warpgate_pdk::exec`'s
// `Result` can represent; the guest's Rust code (this `run` method
// included) never resumes. From the caller's perspective (moon, or this
// crate's own `PluginContainer::call_func_with` in tests), the whole
// `execute_extension`/`initialize_extension` wire call fails outright
// (`WarpgatePluginError::FailedPluginCall`), not a clean
// `ExecuteExtensionOutput { exit_code: 1, report: { "error": ... } } }`
// response. This directly contradicted this crate's "execute_extension
// never panics/traps; every failure is caught into the report" invariant
// for the single most common real-world failure mode (the host tool the
// extension shells out to -- `moon` itself, or `git` -- being missing).
//
// The fix: proactively check whether `program` exists BEFORE calling
// `warpgate_pdk::exec` at all, via `warpgate_pdk::command_exists` (which
// shells out to `which`/`Get-Command`, not to `program` itself, so a
// missing `program` is reported as a normal `false` rather than tripping
// the same `MissingCommand` trap -- `which`/`Get-Command` being absent is
// an accepted, far less likely residual risk that `warpgate_pdk` itself
// takes on for every consumer). This turns "program not found" into the
// clean `CommandError::NotFound` this method already promises to produce,
// without ever calling `exec` for a program we already know is absent.
#[cfg(feature = "pdk")]
impl CommandRunner for MoonCommandRunner {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
        use warpgate_pdk::{get_host_environment, into_virtual_path, ExecCommandInput};

        let host_env = get_host_environment().map_err(|e| classify_host_failure(program, &e.to_string()))?;

        if !warpgate_pdk::command_exists(&host_env, program) {
            return Err(CommandError::NotFound {
                program: program.to_string(),
            });
        }

        let cwd = match into_virtual_path(cwd) {
            Ok(vpath) => Some(vpath),
            Err(e) => return Err(classify_host_failure(program, &e.to_string())),
        };

        let input = ExecCommandInput {
            command: program.to_string(),
            args: args.iter().map(|a| a.to_string()).collect(),
            cwd,
            ..ExecCommandInput::default()
        };

        match warpgate_pdk::exec(input) {
            Ok(output) => Ok(CommandOutput {
                exit_code: Some(output.exit_code),
                stdout: output.stdout,
                stderr: output.stderr,
            }),
            Err(e) => Err(classify_host_failure(program, &e.to_string())),
        }
    }
}

